<script setup lang="ts">
import {computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{vendorAPI}from'../../services/api';import type{Category,VendorProduct}from'../../services/api';import api from'../../services/api';import StatusBadge from'../../components/StatusBadge.vue';import ConfirmDialog from'../../components/ConfirmDialog.vue';
const route=useRoute(),router=useRouter(),editing=computed(()=>typeof route.params.id==='string'),loading=ref(false),saving=ref(false),error=ref(''),fields=ref<Record<string,string>>({}),categories=ref<Category[]>([]),deleteOpen=ref(false),deleting=ref(false),product=ref<VendorProduct|null>(null);
const form=ref({name:'',description:'',price:'' as string|number,original_price:'' as string|number|null,stock:'' as string|number,image:'',category_id:'' as string|number,status:'' as string,status_reason:''});
function validate(){fields.value={};if(!form.value.name.trim())fields.value.name='Name is required.';else if(form.value.name.length>255)fields.value.name='Name may not exceed 255 characters.';if(!form.value.description.trim())fields.value.description='Description is required.';else if(form.value.description.length>5000)fields.value.description='Description may not exceed 5000 characters.';if(form.value.price===''||Number(form.value.price)<0)fields.value.price='Price must be 0 or more.';if(form.value.stock===''||!Number.isInteger(Number(form.value.stock))||Number(form.value.stock)<0)fields.value.stock='Stock must be a whole number of 0 or more.';if(!form.value.category_id)fields.value.category_id='Category is required.';if(form.value.original_price!==''&&form.value.original_price!==null&&Number(form.value.original_price)<=Number(form.value.price))fields.value.original_price='Original price must be higher than price.';return Object.keys(fields.value).length===0}
async function load(){loading.value=true;try{const r=await api.get('/categories');categories.value=(Array.isArray(r.data)?r.data:(r.data?.data||[]))as Category[];if(editing.value){const p=await vendorAPI.getProduct(Number(route.params.id));product.value=p;Object.assign(form.value,{name:p.name,description:p.description,price:p.price,original_price:p.original_price??'',stock:p.stock,image:p.image||'',category_id:p.category_id,status:p.status,status_reason:p.status_reason||''})}}catch(e:any){error.value=e.response?.data?.error||'Could not load product.'}finally{loading.value=false}}
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>5*1024*1024){error.value='Image must be 5 MB or less.';return}loading.value=true;try{form.value.image=await vendorAPI.upload(file)}catch(e:any){error.value=e.response?.data?.error||'Upload failed.'}finally{loading.value=false}}
async function save(){if(!validate())return;saving.value=true;error.value='';try{const payload={name:form.value.name.trim(),description:form.value.description.trim(),price:Number(form.value.price),original_price:form.value.original_price===''||form.value.original_price===null?null:Number(form.value.original_price),stock:Number(form.value.stock),image:form.value.image||undefined,category_id:Number(form.value.category_id)};if(editing.value)await vendorAPI.updateProduct(Number(route.params.id),payload);else await vendorAPI.createProduct(payload);await router.push('/vendor/products')}catch(e:any){error.value=e.response?.data?.error||'Could not save product.';fields.value=e.response?.data?.fields||fields.value}finally{saving.value=false}}
async function remove(){deleting.value=true;try{const r=await vendorAPI.deleteProduct(Number(route.params.id));await router.push({path:'/vendor/products',query:{deleted:r?.message?String(r.message):undefined}})}catch(e:any){error.value=e.response?.data?.error||'Could not delete product.'}finally{deleting.value=false;deleteOpen.value=false}}
onMounted(load)
</script><template><main class="vendor-main"><header class="page-head"><div><p>{{editing?'EDIT':'ADD'}} PRODUCT</p><h1>{{editing?'Edit Product':'Add Product'}}</h1></div><router-link to="/vendor/products">Back to products</router-link></header><div v-if="error" class="alert">{{error}}</div><div v-if="loading" class="state">Loading...</div><form v-else class="product-form" @submit.prevent="save"><div v-if="product?.status==='disabled'" class="disabled-note">Disabled by Kisaku: {{product.status_reason}}<br/>You can edit this product, but only Kisaku can put it back live.</div><div v-if="product" class="status-line">Status: <StatusBadge :status="product.status"/></div><label>Name<input v-model="form.name" maxlength="255" required/><small v-if="fields.name">{{fields.name}}</small></label><label>Description<textarea v-model="form.description" maxlength="5000" required/><small v-if="fields.description">{{fields.description}}</small></label><div class="row"><label>Price (KSh)<input v-model="form.price" type="number" min="0" step="0.01" required/><small v-if="fields.price">{{fields.price}}</small></label><label>Original price<input v-model="form.original_price" type="number" min="0" step="0.01"/><small v-if="fields.original_price">{{fields.original_price}}</small></label></div><div class="row"><label>Stock<input v-model="form.stock" type="number" min="0" step="1" required/><small v-if="fields.stock">{{fields.stock}}</small></label><label>Category<select v-model="form.category_id" required><option value="">Select category</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select><small v-if="fields.category_id">{{fields.category_id}}</small></label></div><label>Product image<div class="upload"><input type="file" accept="image/jpeg,image/png,image/gif,image/webp" :disabled="loading" @change="upload"/><img v-if="form.image" :src="form.image" alt="Product preview"/></div><span class="or-url">Or use an existing image URL</span><input v-model="form.image" type="url" placeholder="https://example.com/image.jpg" :disabled="loading||saving"/><small>JPEG, PNG, GIF or WebP; uploaded files may be up to 5 MB.</small></label><div class="form-actions"><button v-if="editing" type="button" class="delete" :disabled="saving||deleting" @click="deleteOpen=true">Delete</button><button type="submit" class="save" :disabled="saving||loading">{{saving?'Saving...':'Save product'}}</button></div></form><ConfirmDialog :open="deleteOpen" title="Delete product?" message="This product will be deleted. This cannot be undone." confirm-text="Delete" :loading="deleting" @close="deleteOpen=false" @confirm="remove"/></main></template><style scoped>.vendor-main{padding:18px 28px}.page-head{display:flex;justify-content:space-between}.page-head p{margin:0;color:#075397;font-size:.66rem;font-weight:800}.page-head h1{margin:4px 0 18px}.page-head>a{color:#075397}.alert,.disabled-note{margin-bottom:12px;padding:10px;border-radius:6px}.alert{background:#feeaea;color:#b42318}.disabled-note{background:#fff1f1;color:#b42318}.status-line{display:flex;align-items:center;gap:8px}.product-form{display:flex;flex-direction:column;gap:14px;padding:20px;border:1px solid #e6ebf1;border-radius:8px;background:#fff}.product-form label{display:flex;flex-direction:column;gap:6px;font-size:.82rem;font-weight:750}.product-form input,.product-form textarea,.product-form select{width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:6px}.product-form textarea{min-height:130px}.product-form small{color:#b42318}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.upload{display:flex;align-items:center;gap:12px}.upload input{padding:7px}.upload img{width:72px;height:72px;border-radius:6px;object-fit:cover}.or-url{margin-top:4px;color:#526579;font-size:.78rem;font-weight:700}.form-actions{display:flex;justify-content:flex-end;gap:8px}.form-actions button{height:42px;padding:0 14px;border-radius:6px;font-weight:800}.save{border:0;background:#ff7900;color:#fff}.delete{border:1px solid #b42318;background:#fff;color:#b42318}.state{padding:30px;text-align:center}@media(max-width:700px){.vendor-main{padding:14px}.row{grid-template-columns:1fr}.page-head{align-items:center}}</style>